import java.util.*;

class Box<T> {
    private final T value;

    Box(T value) {
        this.value = value;
    }

    T get() {
        return value;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Box<String> text = new Box<>(sc.next());
        Box<Integer> number = new Box<>(sc.nextInt());
        System.out.println("text=" + text.get() + " number=" + number.get());
    }
}

