import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String kind = sc.next();
        String raw = sc.next();
        Object value;
        Class<?> type;
        if (kind.equals("integer")) {
            value = Integer.parseInt(raw);
            type = Integer.class;
        } else {
            value = raw;
            type = String.class;
        }
        System.out.println("type=" + type.getSimpleName() + " match=" + type.isInstance(value));
    }
}

