import java.util.*;

public class Main {
    // 型消去のため List<String> と List<Integer> は同じ形になり、引数の型だけでは
    // 多重定義できない。名前を分けて区別する。
    static int countWords(List<String> values) {
        return values.size();
    }

    static int countNumbers(List<Integer> values) {
        return values.size();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<String> words = new ArrayList<>();
        List<Integer> numbers = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String token = sc.next();
            if (token.matches("-?\\d+")) {
                numbers.add(Integer.parseInt(token));
            } else {
                words.add(token);
            }
        }
        System.out.println("words=" + countWords(words)
                + " numbers=" + countNumbers(numbers));
    }
}
